     1	// Input checks for request bodies and query strings. Each parser returns the clean value or throws a
     2	// ValidationError, which the server turns into a 400 reply.
     3	
     4	export class ValidationError extends Error {
     5	  constructor(message) {
     6	    super(message)
     7	    this.name = 'ValidationError'
     8	  }
     9	}
    10	
    11	const GROUP_ID = /^[a-z][a-z0-9-]{0,29}$/
    12	const MEMBER_NAME = /^[A-Za-z][A-Za-z0-9_-]{0,29}$/
    13	const MIN_MEMBERS = 2
    14	const MAX_MEMBERS = 20
    15	const MAX_GROUP_NAME_LENGTH = 100
    16	const MAX_DESCRIPTION_LENGTH = 200
    17	const CENTS_PER_UNIT = 100
    18	const MAX_AMOUNT_CENTS = 1_000_000 * CENTS_PER_UNIT
    19	// Digits with at most two decimals, as String() writes a number: "12", "12.5", "4.35".
    20	const TWO_DECIMALS = /^[0-9]+(\.[0-9]{1,2})?$/
    21	
    22	const AMOUNT_MESSAGE = 'amount must be a number from 0.01 to 1000000 with at most 2 decimals'
    23	const SPLIT_MESSAGE = 'split must be a non-empty list of different members of the group'
    24	
    25	const isText = (v, max) => typeof v === 'string' && v.trim() !== '' && v.length <= max
    26	
    27	export function parseGroupId(v) {
    28	  if (typeof v !== 'string' || !GROUP_ID.test(v)) {
    29	    throw new ValidationError('id must be 1 to 30 characters of a-z, 0-9 or -, starting with a letter')
    30	  }
    31	  return v
    32	}
    33	
    34	export function parseGroupName(v) {
    35	  if (!isText(v, MAX_GROUP_NAME_LENGTH)) {
    36	    throw new ValidationError(`name must be a non-empty string of at most ${MAX_GROUP_NAME_LENGTH} characters`)
    37	  }
    38	  return v
    39	}
    40	
    41	// A list of 2 to 20 member names, each used once. Names are case-sensitive: "Ann" and "ann" are two people.
    42	export function parseMembers(v) {
    43	  if (!Array.isArray(v) || v.length < MIN_MEMBERS || v.length > MAX_MEMBERS) {
    44	    throw new ValidationError(`members must be an array of ${MIN_MEMBERS} to ${MAX_MEMBERS} names`)
    45	  }
    46	  if (!v.every(name => typeof name === 'string' && MEMBER_NAME.test(name))) {
    47	    throw new ValidationError('member names must be 1 to 30 characters of A-Z, a-z, 0-9, _ or -, starting with a letter')
    48	  }
    49	  if (new Set(v).size !== v.length) throw new ValidationError('members must not repeat a name')
    50	  return [...v]
    51	}
    52	
    53	export function parseDescription(v) {
    54	  if (!isText(v, MAX_DESCRIPTION_LENGTH)) {
    55	    throw new ValidationError(`description must be a non-empty string of at most ${MAX_DESCRIPTION_LENGTH} characters`)
    56	  }
    57	  return v
    58	}
    59	
    60	// Amounts arrive as numbers such as 12.5 or 4.35 and are kept as whole cents, so sums never drift.
    61	export function parseAmount(v) {
    62	  if (typeof v !== 'number' || !TWO_DECIMALS.test(String(v))) throw new ValidationError(AMOUNT_MESSAGE)
    63	  // Rounded, not truncated: 4.35 * 100 is 434.99999999999994 in floating point.
    64	  const cents = Math.round(v * CENTS_PER_UNIT)
    65	  if (cents < 1 || cents > MAX_AMOUNT_CENTS) throw new ValidationError(AMOUNT_MESSAGE)
    66	  return cents
    67	}
    68	
    69	// A name that must belong to one of members; message says which field was wrong.
    70	export function parseMember(v, members, message) {
    71	  if (typeof v !== 'string' || !members.includes(v)) throw new ValidationError(message)
    72	  return v
    73	}
    74	
    75	// Who shares an expense: a non-empty list of members without repeats. Missing means every member, in group order.
    76	export function parseSplit(v, members) {
    77	  if (v === undefined) return [...members]
    78	  if (!Array.isArray(v) || v.length === 0 || new Set(v).size !== v.length) throw new ValidationError(SPLIT_MESSAGE)
    79	  if (!v.every(name => typeof name === 'string' && members.includes(name))) throw new ValidationError(SPLIT_MESSAGE)
    80	  return [...v]
    81	}
    82	// Expense and payment handlers, same contract as lib/groups.mjs: they return a new store instead of changing
    83	// the one they get.
    84	import { NOT_FOUND, findGroup } from './groups.mjs'
    85	import { expenseView, paymentView } from './ledger.mjs'
    86	import { parseAmount, parseDescription, parseMember, parseSplit, ValidationError } from './validate.mjs'
    87	
    88	const byId = (a, b) => a.id - b.id
    89	
    90	// The fields of a new expense in group, from a request body. Throws ValidationError on the first bad field.
    91	export function parseExpense(group, body) {
    92	  return {
    93	    description: parseDescription(body.description),
    94	    payer: parseMember(body.payer, group.members, 'payer must be a member of the group'),
    95	    amount: parseAmount(body.amount),
    96	    split: parseSplit(body.split, group.members),
    97	  }
    98	}
    99	
   100	export function addExpense({ state, params, body }) {
   101	  const group = findGroup(state, params[0])
   102	  if (!group) return NOT_FOUND
   103	  const expense = { id: state.nextExpenseId, group: group.id, ...parseExpense(group, body) }
   104	  const next = { ...state, expenses: [...state.expenses, expense], nextExpenseId: state.nextExpenseId + 1 }
   105	  return { status: 201, body: expenseView(expense), state: next }
   106	}
   107	
   108	export function listExpenses({ state, params }) {
   109	  const group = findGroup(state, params[0])
   110	  if (!group) return NOT_FOUND
   111	  const expenses = state.expenses.filter(e => e.group === group.id).sort(byId).map(expenseView)
   112	  return { status: 200, body: { expenses } }
   113	}
   114	
   115	const findExpense = (state, [groupId, expenseId]) =>
   116	  state.expenses.find(e => e.group === groupId && String(e.id) === expenseId)
   117	
   118	// Changes the fields the body gives, each checked as on POST; fields left out keep their value.
   119	export function editExpense({ state, params, body }) {
   120	  const group = findGroup(state, params[0])
   121	  const old = group && findExpense(state, params)
   122	  if (!old) return NOT_FOUND
   123	  const changes = {}
   124	  if ('description' in body) changes.description = parseDescription(body.description)
   125	  if ('payer' in body) changes.payer = parseMember(body.payer, group.members, 'payer must be a member of the group')
   126	  if ('amount' in body) changes.amount = parseAmount(body.amount)
   127	  if ('split' in body) changes.split = parseSplit(body.split, group.members)
   128	  const edited = { ...old, ...changes }
   129	  const next = { ...state, expenses: state.expenses.map(e => (e === old ? edited : e)) }
   130	  return { status: 200, body: expenseView(edited), state: next }
   131	}
   132	
   133	export function deleteExpense({ state, params }) {
   134	  const expense = findExpense(state, params)
   135	  if (!expense) return NOT_FOUND
   136	  return { status: 204, state: { ...state, expenses: state.expenses.filter(e => e !== expense) } }
   137	}
   138	
   139	export function addPayment({ state, params, body }) {
   140	  const group = findGroup(state, params[0])
   141	  if (!group) return NOT_FOUND
   142	  const message = 'from and to must be two different members of the group'
   143	  const from = parseMember(body.from, group.members, message)
   144	  const to = parseMember(body.to, group.members, message)
   145	  if (from === to) throw new ValidationError(message)
   146	  const payment = { id: state.nextPaymentId, group: group.id, from, to, amount: parseAmount(body.amount) }
   147	  const next = { ...state, payments: [...state.payments, payment], nextPaymentId: state.nextPaymentId + 1 }
   148	  return { status: 201, body: paymentView(payment), state: next }
   149	}
   150	
   151	export function listPayments({ state, params }) {
   152	  const group = findGroup(state, params[0])
   153	  if (!group) return NOT_FOUND
   154	  const payments = state.payments.filter(p => p.group === group.id).sort(byId).map(paymentView)
   155	  return { status: 200, body: { payments } }
   156	}
   157	// HTTP entry point: finds the route, reads the JSON body of the routes that take one, runs the handler and
   158	// saves the store after every change. Env: PORT (default 3000), DATA_FILE (default groups.json).
   159	import { existsSync } from 'node:fs'
   160	import { createServer } from 'node:http'
   161	import { dirname, resolve } from 'node:path'
   162	import { errorReply, parseJsonObject, readBody, send } from './lib/http.mjs'
   163	import { findRoute } from './lib/routes.mjs'
   164	import { load, save } from './lib/store.mjs'
   165	
   166	const DEFAULT_PORT = 3000
   167	const MAX_PORT = 65535
   168	
   169	// Builds the server around the store in dataFile. The store is kept in memory; each change is saved before it
   170	// replaces the in-memory copy, so a failed save changes nothing.
   171	export function createApp(dataFile) {
   172	  let state = load(dataFile)
   173	  return createServer(async (req, res) => {
   174	    try {
   175	      // Prefixing the origin keeps a request path like //host/groups a path, not a host.
   176	      const url = new URL(`http://localhost${req.url}`)
   177	      const route = findRoute(req.method, url.pathname)
   178	      if (!route) return send(res, { status: 404, body: { error: 'not found' } })
   179	      const body = route.takesBody ? parseJsonObject(await readBody(req)) : undefined
   180	      const reply = route.handler({ state, params: route.params, query: url.searchParams, body })
   181	      if (reply.state) {
   182	        save(dataFile, reply.state)
   183	        state = reply.state
   184	      }
   185	      send(res, reply)
   186	    } catch (err) {
   187	      send(res, errorReply(err))
   188	    }
   189	  })
   190	}
   191	
   192	function fail(message) {
   193	  console.error(`cannot start: ${message}`)
   194	  process.exitCode = 1
   195	}
   196	
   197	// A plain message for the OS errors a bad DATA_FILE gives; any other error keeps its own.
   198	function loadErrorMessage(err, file) {
   199	  if (err.code === 'EISDIR') return `DATA_FILE ${file} is a folder, not a file`
   200	  if (err.code === 'EACCES') return `cannot read DATA_FILE ${file}: permission denied`
   201	  return err.message
   202	}
   203	
   204	function main() {
   205	  const port = Number(process.env.PORT || DEFAULT_PORT)
   206	  if (!Number.isInteger(port) || port < 0 || port > MAX_PORT) {
   207	    return fail(`PORT must be a whole number from 0 to ${MAX_PORT}, got "${process.env.PORT}"`)
   208	  }
   209	  const file = process.env.DATA_FILE || 'groups.json'
   210	  // Without this check the server would start, then answer 500 to every change it cannot save.
   211	  if (!existsSync(dirname(resolve(file)))) return fail(`folder for DATA_FILE ${file} does not exist`)
   212	  let server
   213	  try {
   214	    server = createApp(file)
   215	  } catch (err) {
   216	    return fail(loadErrorMessage(err, file))
   217	  }
   218	  server.on('error', err => fail(err.message))
   219	  server.listen(port, '127.0.0.1', () => {
   220	    console.log(`listening on http://127.0.0.1:${server.address().port}`)
   221	  })
   222	}
   223	
   224	if (import.meta.main) main()
   225	// HTTP helpers: reading a JSON body, sending JSON replies and turning errors into replies.
   226	import { ValidationError } from './validate.mjs'
   227	
   228	export const MAX_BODY_BYTES = 10 * 1024
   229	
   230	export class HttpError extends Error {
   231	  constructor(status, message) {
   232	    super(message)
   233	    this.status = status
   234	  }
   235	}
   236	
   237	// Reads the whole body as UTF-8. Past MAX_BODY_BYTES it stops keeping chunks but still drains the upload,
   238	// so the 413 reply reaches the client instead of a reset connection.
   239	export function readBody(req) {
   240	  return new Promise((resolve, reject) => {
   241	    const chunks = []
   242	    let size = 0
   243	    req.on('data', chunk => {
   244	      size += chunk.length
   245	      if (size <= MAX_BODY_BYTES) chunks.push(chunk)
   246	    })
   247	    req.on('end', () => {
   248	      if (size > MAX_BODY_BYTES) reject(new HttpError(413, 'body too large'))
   249	      else resolve(Buffer.concat(chunks).toString('utf8'))
   250	    })
   251	    req.on('error', reject)
   252	  })
   253	}
   254	
   255	export function parseJsonObject(text) {
   256	  let value
   257	  try {
   258	    value = JSON.parse(text)
   259	  } catch {
   260	    throw new HttpError(400, 'invalid JSON')
   261	  }
   262	  if (value === null || typeof value !== 'object' || Array.isArray(value)) {
   263	    throw new HttpError(400, 'body must be a JSON object')
   264	  }
   265	  return value
   266	}
   267	
   268	// Sends { status, body }: body as JSON, or no body at all when it is undefined (204).
   269	export function send(res, { status, body }) {
   270	  if (body === undefined) {
   271	    res.writeHead(status).end()
   272	    return
   273	  }
   274	  const text = JSON.stringify(body)
   275	  res.writeHead(status, { 'content-type': 'application/json', 'content-length': Buffer.byteLength(text) })
   276	  res.end(text)
   277	}
   278	
   279	export function errorReply(err) {
   280	  if (err instanceof HttpError) return { status: err.status, body: { error: err.message } }
   281	  if (err instanceof ValidationError) return { status: 400, body: { error: err.message } }
   282	  // An OS error (ENOENT, EACCES, ...) is logged as one line; any other error keeps its stack.
   283	  console.error(err.code ? [err.code, err.syscall, err.path].filter(Boolean).join(' ') : err)
   284	  return { status: 500, body: { error: 'internal error' } }
   285	}
